function openResultShareMenu(button){
const previous=document.getElementById('result-share-menu');if(previous){const same=previous._anchor===button;previous.remove();if(same)return}
const menu=document.createElement('div');menu.id='result-share-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','分享');menu._anchor=button;menu.innerHTML='<button type="button" role="menuitem" data-copy><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h4M9 12h6M9 16h5"/></svg><span>拷贝链接</span></button><button type="button" role="menuitem" data-welink><span class="share-welink-icon">W</span><span>分享到 WeLink</span></button>';document.body.append(menu);button.setAttribute('aria-expanded','true');button.setAttribute('aria-haspopup','menu');
const rect=button.getBoundingClientRect();menu.style.left=Math.min(innerWidth-240,Math.max(12,rect.left-12))+'px';menu.style.top=Math.max(12,rect.top-menu.offsetHeight-10)+'px';
const close=()=>{menu.remove();button.setAttribute('aria-expanded','false');document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',keys)};
function outside(e){if(!menu.contains(e.target)&&!button.contains(e.target))close()}
function keys(e){if(e.key==='Escape'){close();button.focus()}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const items=[...menu.querySelectorAll('button')],index=items.indexOf(document.activeElement);items[(index+(e.key==='ArrowDown'?1:items.length-1))%items.length].focus()}}
document.addEventListener('pointerdown',outside);document.addEventListener('keydown',keys);
menu.querySelector('[data-copy]').onclick=async()=>{const status=button.closest('.stock-feedback')?.querySelector('[role=status]');try{await navigator.clipboard.writeText(new URL('stock-share.html',location.href).href);if(status)status.textContent='链接已复制'}catch{if(status)status.textContent='复制失败，请重试'}close()};
menu.querySelector('[data-welink]').onclick=()=>{close();openWeLinkQueryShare()};
}

function openWeLinkQueryShare(){
const data={title:'查询库存现有量及可用量',request:'查询库存现有量及可用量：查询华东库存组织主控板的现有量及可用量。',owner:'张小强',recipient:'李小梅',organization:'华东库存组织',agent:'库存作业智能体',time:'2026/10/30 09:21:54',columns:['库存组织','物料编码','物料描述','子库','物料版本','货位','批次编码','现有量：主单位数量（单位）','现有量：辅助单位数量（单位）','可预留量：主单位数量（单位）','可处理量：主单位数量（单位）'],rows:Array.from({length:4},(_,i)=>['华东库存组织','PCB-A100','主控板',i%2?'WIP01':'RM01','A.1','A-'+String(i*3+1).padStart(2,'0'),'LOT-202610'+[20,23,22,21][i]+'-'+String(i*3+1).padStart(3,'0'),(2100-i*120).toLocaleString('en-US')+' 块',(21-i*1.2).toFixed(1).replace('.0','')+' 箱',(1600-i*90).toLocaleString('en-US')+' 块',(2000-i*120).toLocaleString('en-US')+' 块']),conditions:[['查询对象','库存现有量及可用量'],['库存组织','华东库存组织'],['物料描述','主控板']]};
document.getElementById('welink-collaboration-dialog')?.remove();const d=document.createElement('dialog');d.id='welink-collaboration-dialog';const close=document.createElement('button');close.className='welink-popup-close';close.setAttribute('aria-label','关闭WeLink分享');close.textContent='×';const frame=document.createElement('iframe');frame.title='分享到 WeLink';frame.src='https://erp-assistant-workbench-hao.mightyaspen68.chatgpt.site/welink-sharing#data='+encodeURIComponent(JSON.stringify(data));d.append(close,frame);document.body.append(d);close.onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal();
}
